  <script>
import gsap from 'gsap';
import {
    onMounted,
    nextTick,
    onUnmounted
} from 'vue';

  export default {
    name: 'AcquisitionsWidget',
    setup() {
      var midOutlineTl = gsap.timeline();
      onMounted(async () => {
        await nextTick();
        var topPaths = document.querySelectorAll('.acquisitionswidget .glasser .top-banner svg path');
        var midOutlineContent = document.querySelectorAll('.acquisitionswidget .glasser .mid-display svg path:not(.outline)');
        var bottomIcons = document.querySelectorAll('.acquisitionswidget .glasser .bottom-icons svg');

        function animatePathRandAcquisition(path) {
          gsap.to(path, {
            duration: 1, // Random duration between 0.3 - 0.8s
            opacity: () => Math.random() > 0.5 ? 0 : 1, // Randomly make it disappear or appear
            ease: "power1.inOut",
            stagger: 0.1,
            onComplete: () => {
              setTimeout(() => animatePathRandAcquisition(path), Math.random() * 1000);
            }
          });
        };
        topPaths.forEach(path => {
         setTimeout(()=> animatePathRandAcquisition(path), Math.random()*1000);
        });

        midOutlineTl.set("#maskRect", {
          width: "0%",
        });
        midOutlineTl.set(midOutlineContent, {
          opacity: 0,
        });
        midOutlineTl.set(bottomIcons, {
          opacity: 0,
        });
        midOutlineTl.to("#maskRect", { 
          width: "100%", 
          duration: 1, 
          ease: "linear",
          delay: 0.5,
          onComplete: () => {
            midOutlineContent.forEach(path => {
              gsap.to(path, {
                opacity: 1,
                duration: 0.3,
                stagger: 0.3,
                ease: "power1.inOut"
              });
            });
          }
         });
         midOutlineTl.to(bottomIcons, {
          opacity: 1,
          duration: .8,
          stagger: 0.5,
          ease: "power1.inOut",
          delay: 0.5,
         })
      });
      onUnmounted(async () => {
      })
    }
  };
  </script>
  
